  "settings.retentionMonthlyInfo": "Conserve une sauvegarde pour chacun des N derniers mois calendaires ayant une sauvegarde.",
  "settings.retentionYearlyInfo": "Conserve une sauvegarde pour chacune des N dernières années civiles ayant une sauvegarde. S'il y a moins d'années, la plus ancienne est conservée aussi.",
  "settings.retentionOffsiteTitle": "Rétention hors site",
  "settings.retentionOffsiteHint": "Une politique distincte pour le dépôt hors-site, pour le conserver plus longtemps comme archive. Tout à 0 = conserver chaque sauvegarde hors-site (pas de purge hors-site).",
  "settings.ownRetentionTitle": "Règles de rétention par source",
  "settings.ownOffsiteRetention": "Règles de rétention hors-site propres",
  "settings.ownOffsiteRetentionFor": "Règles de rétention hors-site propres pour {source}",
  "settings.ownOffsiteRetentionHint": "Une source peut garder les sauvegardes de son dépôt hors-site selon ses propres règles au lieu des règles hors-site communes ci-dessus. Une source sans règles propres utilise les règles communes.",
  "settings.ownOffsiteRetentionToggleHint": "Activé : le dépôt hors-site de cette source garde ses sauvegardes selon les cinq règles ci-dessous, qui partent des valeurs hors-site communes. Désactivé : il utilise les règles hors-site communes. Tout à 0 garde chaque sauvegarde hors-site de cette source.",
  "settings.retentionExtraTargets": "Les destinations hors site supplémentaires gardent leurs propres règles, que vous réglez dans la carte Copie hors site de chaque section.",
  "settings.retentionOffsiteScope": "Ces règles s'appliquent à la destination hors-site principale de chaque section, c'est-à-dire l'adresse de son champ hors-site. Toute autre copie hors-site, y compris une issue d'une destination, garde ses propres règles. Si ses valeurs sont toutes à 0, BombVault ne l'élague jamais.",
  "settings.retentionCombineInfo": "Les cinq règles se combinent avec OU : une sauvegarde survit si une seule règle la conserverait. Elles ne s'additionnent pas en un nombre fixe. S'applique séparément à chaque élément sauvegardé.",

  // Off-site (rclone)
  "rclone.title": "Hors site (rclone)",
  "rclone.hint": "Collez une configuration rclone pour sauvegarder dans le cloud (Backblaze B2, S3, Google Drive, …). Elle est stockée chiffrée. SMB/NFS n'ont pas besoin de rclone : montez le partage sur Unraid et pointez-y un chemin de sauvegarde.",
  "rclone.configured": "Remotes configurés",
  "rclone.pathHint": "Puis définissez un chemin de sauvegarde sur « rclone:<remote>:<bucket>/path » pour envoyer cette section hors site.",
  "cloud.title": "Identifiants cloud partagés (S3 / restic REST)",
  "cloud.hint": "Identifiants pour les backends restic distants, sans rclone. Après l'enregistrement, définissez un chemin de sauvegarde vers un dépôt distant, p. ex. s3:s3.amazonaws.com/bucket/path, rest:http://host:8000/repo ou sftp:user@host:/repo. Les secrets sont stockés chiffrés et ne sont plus affichés.",
  "cloud.secretSet": "enregistré, laisser vide pour conserver",
  "cloud.storageClass.label": "Classe de stockage off-site",
  "cloud.storageClass.default": "(par défaut du fournisseur)",
  "cloud.storageClass.hint": "S'applique uniquement aux backends S3 natifs (dépôts commençant par s3:). Les niveaux d'archivage profond (Glacier Flexible Retrieval, Deep Archive) ne sont volontairement pas proposés car ils cassent la restauration restic.",
  "cloud.credSets.title": "Ensembles d'identifiants supplémentaires",
  "cloud.credSets.hint": "Donnez à une ou plusieurs destinations hors site leurs propres identifiants S3 ou restic REST, au lieu de partager ceux ci-dessus.",
  "cloud.credSets.add": "Ajouter un ensemble d'identifiants",
  "cloud.credSets.name": "Nom",
  "cloud.credSets.none": "Aucun ensemble d'identifiants supplémentaire pour le moment.",
  "cloud.credSets.kept": "{name} (identifiants conservés)",
  "export.encrypt.hint": "Les dépôts restic sont déjà chiffrés. Ceci chiffre en option les artefacts d'export en clair (tar.gz de conteneur et de VM avec leurs fichiers xml, et le zip flash) avec age, afin qu'ils puissent être stockés ou déplacés hors du serveur en toute sécurité.",
  "export.encrypt.ageInfo": "age (age-encryption.org) est un outil de chiffrement de fichiers petit et moderne, une alternative plus simple à GPG pour sceller un fichier pour un ou plusieurs destinataires.",
  "export.encrypt.enable": "Chiffrer les exports avec age",
  "export.encrypt.enableHint": "Lorsqu'activé, les exports de conteneurs, de VM et flash sont scellés avec age avant d'être écrits sur le disque, et reçoivent un suffixe .age.",
  "export.encrypt.kitSealed": "Le kit de récupération est scellé lui aussi et arrive sous le nom bombvault-recovery-kit.md.age. Il reste du texte lisible (ASCII armor), vous pouvez donc toujours le coller dans un gestionnaire de mots de passe ou l'imprimer, mais il vous faudra votre clé privée age pour l'ouvrir : conservez cette clé à un endroit qui ne dépend pas du kit lui-même.",
  "export.encrypt.recipients": "Destinataires age",
  "export.encrypt.recipientsHint": "Un destinataire par ligne. Utilisez une clé publique age (age1...) ou une clé publique SSH. La clé privée correspondante est nécessaire pour déchiffrer hors du serveur. Avec le chiffrement activé et aucun destinataire valide, l'export échoue au lieu d'écrire du texte en clair.",
  "export.encrypt.recipientsPlaceholder": "age1qz...\nssh-ed25519 AAAA...",
  "export.encrypt.recipientsRequired": "Ajoutez au moins un destinataire age, sinon l'export chiffré échouera.",
  "rclone.save": "Enregistrer la config",

