  "integrity.pruneAsk": "Élaguer {section} ? L'élagage applique maintenant votre rétention : les sauvegardes au-delà de vos règles sont supprimées et l'espace est libéré. Sans règles, seul de l'espace est libéré. Cela peut prendre du temps.",
