  "idle.toggleHint": "Une sauvegarde planifiée de ce conteneur attend tant que l'application est occupée et démarre dès qu'elle est au repos, ou quand l'attente est écoulée. Un serveur multimédia est au repos quand il ne diffuse pas, toute autre application quand le CPU et le trafic restent bas (Paramètres, Planning). Les sauvegardes manuelles n'attendent jamais.",
