  "offsite.prune.info": "Cette étape indique seulement ce qui se passe, elle ne règle rien. Le fait que cette copie soit élaguée dépend de l'append-only de l'étape 4 et des valeurs de conservation dans Paramètres, Destinations. Pour élaguer malgré tout une copie append-only, lancez restic forget --prune côté stockage, soit selon sa propre planification, soit en montant brièvement un second serveur REST sans append-only, en élaguant à travers lui puis en l'arrêtant.",
