  "recovery.abTitle": "Importer depuis le plugin Appdata.Backup",
  "recovery.abIntro": "Transforme les archives écrites par le plugin Appdata.Backup en points de restauration des conteneurs correspondants, chacun daté du moment où le plugin l'a créé. Les archives sont seulement lues, jamais modifiées ni supprimées. Chacune est décompressée à côté du dépôt, sauvegardée, puis la copie décompressée est supprimée ; cet emplacement doit donc avoir de la place pour la plus grande archive.",
