  "mcp.rotateConfirm": "{name} reçoit une nouvelle clé et l'ancienne cesse aussitôt de fonctionner. Mettez à jour tous les clients qui l'utilisent.",
  "mcp.rotated": "Clé remplacée",
  "mcp.revoke": "Révoquer",
