  "mcp.logCalls": "Appels",
  "mcp.logKeptHint": "BombVault garde les appels de chaque clé pendant un mois au plus : les 500 lancements et annulations réussis les plus récents, et les 200 autres appels les plus récents (lectures, refus et erreurs). Il n'enregistre jamais ce que l'assistant a envoyé, ni la clé elle-même.",
