  "mcp.outcomeOther": "Terminé avec {code}",
  "api.title": "Jetons d'API",
  "api.hint": "Des jetons pour les scripts, les tableaux de bord et la domotique. Un jeton ouvre l'API sous /api/v1 et rien d'autre. Les restaurations, les suppressions et les réglages restent dans cette interface web.",
  "api.addressLabel": "Adresse de l'API",
  "api.addressHint": "Envoyez le jeton sous la forme Authorization: Bearer <token> ou dans l'en-tête X-API-Key. La description de toutes les routes se trouve sous /api/v1/openapi.json et ne demande aucun jeton.",
  "api.viewDescription": "Ouvrir la description",
  "api.noPasswordWarning": "Aucun mot de passe de connexion n'est défini, donc cette interface web est ouverte à tout le monde sur votre réseau, et qui peut l'ouvrir peut aussi créer un jeton.",
  "api.needsPasswordForHost": "Cette page a été ouverte sous {host}. Sans mot de passe de connexion, les jetons ne peuvent être créés et remplacés que depuis une adresse IP ou un nom local comme tower ou tower.local. Définissez un mot de passe de connexion ou ouvrez BombVault par son adresse locale.",
  "api.labelLabel": "Nom du jeton",
  "api.labelPlaceholder": "Script d'état nocturne",
  "api.allowStartHint": "Avec cette option activée, le jeton peut lancer la sauvegarde d'un élément, d'une section entière ou la sauvegarde complète, et annuler les sauvegardes qu'il a lancées : au plus {n} par heure, {minutes} minutes d'écart pour le même élément et {perDay} par élément et par jour. Une sauvegarde arrête les conteneurs en cours d'exécution jusqu'à sa fin. Avec l'option désactivée, le jeton ne peut que lire.",
