  "anomaly.title": "Anomalies",
  "anomaly.cardHint": "BombVault compare chaque sauvegarde d'un élément avec les précédentes et signale ce qui ne colle pas : beaucoup plus de données nouvelles que d'habitude, la plupart des données réécrites, une source qui a fortement diminué ou grossi, un dump de base de données qui a rétréci, une sauvegarde soudainement bien plus longue, des échecs répétés, un test de restauration qui ne passe plus, et un disque bientôt plein. La plupart des contrôles ont d'abord besoin de 10 sauvegardes d'un élément. Un élément ZFS est vérifié jeu de données par jeu de données, si bien qu'un jeu de données enfant vidé se remarque même dans une grande arborescence.",
